INSERT IGNORE INTO job_titles (title, tasks, created_at, updated_at) VALUES ('كاتب استعلامات', '["أداء المهام الأساسية والفنية المتعلقة بوظيفة كاتب استعلامات بكفاءة وفعالية.","الالتزام بسياسات وإجراءات العمل المعتمدة في الشركة.","التعاون المستمر مع أعضاء الفريق لتحقيق أهداف القسم.","إعداد وتقديم التقارير الدورية المطلوبة من الإدارة المباشرة.","المحافظة التامة على سرية المعلومات الخاصة بالعمل والعملاء.","تطوير المهارات الشخصية والمهنية بشكل مستمر لمواكبة متطلبات العمل.","استخدام الموارد المتاحة بشكل أمثل لتقليل الهدر وتحسين الإنتاجية.","التعامل باحترافية مع المشكلات الطارئة وإيجاد حلول سريعة لها.","الرد على الاستفسارات والتواصل الفعال مع الأطراف المعنية.","المساهمة في تحسين بيئة العمل وتقديم مقترحات بناءة لتطوير الأداء.","تنفيذ المهام الإضافية التي يكلف بها المدير المباشر في حدود الاختصاص.","الالتزام بمواعيد العمل الرسمية وقواعد الحضور والانصراف بدقة."]', NOW(), NOW());
